import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

SAMPLE = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


def run(*args, stdin=b""):
    env = dict(os.environ, PYTHONPATH=ROOT + os.pathsep + os.environ.get("PYTHONPATH", ""))
    if isinstance(stdin, str):
        stdin = stdin.encode("utf-8")
    p = subprocess.run([sys.executable, "-m", "pennywise", *args], input=stdin,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=ROOT, env=env)
    return p.returncode, p.stdout.decode("utf-8"), p.stderr.decode("utf-8")


class CliTestCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, content, name="ledger.txt", mode="w"):
        path = os.path.join(self.tmp.name, name)
        if mode == "wb":
            with open(path, "wb") as f:
                f.write(content)
        else:
            with open(path, "w", encoding="utf-8", newline="") as f:
                f.write(content)
        return path


class BalanceCommandTest(CliTestCase):
    def test_balance(self):
        self.assertEqual(run("balance", self.write(SAMPLE)), (0, "1557.50\n", ""))

    def test_balance_json(self):
        code, out, err = run("balance", self.write(SAMPLE), "--json")
        self.assertEqual(code, 0)
        self.assertEqual(json.loads(out), {"balance": "1557.50"})

    def test_balance_stdin(self):
        self.assertEqual(run("balance", "-", stdin=SAMPLE), (0, "1557.50\n", ""))

    def test_balance_empty_and_negative_zero(self):
        self.assertEqual(run("balance", self.write(""))[:2], (0, "0.00\n"))
        self.assertEqual(run("balance", "-", stdin="2024-03-01 x -0\n")[:2], (0, "0.00\n"))

    def test_balance_utf8(self):
        path = self.write("2024-03-01 café 1 crème brûlée\n2024-03-02 x 2\n")
        self.assertEqual(run("balance", path)[:2], (0, "3.00\n"))


class ExitCodeTest(CliTestCase):
    def test_bad_ledger(self):
        code, out, err = run("balance", self.write("# c\n\n2024-03-01 x abc\n"))
        self.assertEqual(code, 1)
        self.assertEqual(out, "")
        self.assertIn("line 3", err)

    def test_bad_ledger_stdin_json(self):
        code, out, err = run("balance", "-", "--json", stdin="2024-02-30 x 1\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 1", err)

    def test_missing_file(self):
        code, out, err = run("balance", os.path.join(self.tmp.name, "nope.txt"))
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_directory(self):
        self.assertEqual(run("balance", self.tmp.name)[:2], (2, ""))

    def test_undecodable(self):
        path = self.write(b"2024-03-01 x 1 \xff\xfe\n", mode="wb")
        self.assertEqual(run("balance", path)[:2], (2, ""))

    def test_no_command(self):
        self.assertEqual(run()[:2], (2, ""))

    def test_unknown_command(self):
        self.assertEqual(run("bogus")[:2], (2, ""))

    def test_bad_option(self):
        self.assertEqual(run("balance", self.write(SAMPLE), "--nope")[:2], (2, ""))

    def test_missing_file_argument(self):
        self.assertEqual(run("balance")[:2], (2, ""))


if __name__ == "__main__":
    unittest.main()
import datetime
import unittest
from decimal import Decimal

import pennywise
from pennywise import Entry, ParseError, balance, format_amount, format_entry, parse

SAMPLE = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


class PublicApiTest(unittest.TestCase):
    def test_exports(self):
        for name in ("parse", "ParseError", "balance", "Entry", "format_amount", "format_entry"):
            self.assertTrue(hasattr(pennywise, name), name)


class ParseSampleTest(unittest.TestCase):
    def test_sample(self):
        entries = parse(SAMPLE)
        self.assertEqual(len(entries), 3)
        self.assertEqual(entries[0], Entry(datetime.date(2024, 3, 1), "salary", Decimal("2500.00"), "March pay"))
        self.assertEqual(entries[1].note, "weekly shop")
        third = entries[2]
        self.assertEqual(third.date, datetime.date(2024, 3, 5))
        self.assertEqual(third.category, "rent")
        self.assertEqual(third.amount, Decimal("-900"))
        self.assertIsInstance(third.amount, Decimal)
        self.assertEqual(third.note, "")

    def test_entry_is_immutable(self):
        e = parse("2024-03-01 x 1")[0]
        with self.assertRaises(AttributeError):
            e.note = "y"

    def test_empty(self):
        self.assertEqual(parse(""), [])

    def test_crlf(self):
        entries = parse("# c\r\n2024-03-01 a 1 note\r\n\r\n2024-03-02 b 2\r\n")
        self.assertEqual([e.note for e in entries], ["note", ""])
        self.assertEqual(entries[1].amount, Decimal("2"))


class WhitespaceAndCommentsTest(unittest.TestCase):
    def test_whitespace_only_and_indented_comment_skipped(self):
        self.assertEqual(parse("   \n\t\t\n \t \n   # note\n\t# x\n"), [])

    def test_leading_trailing_whitespace(self):
        e = parse(" \t 2024-03-01\tFood \t -1.5 \t lunch out \t ")[0]
        self.assertEqual(e, Entry(datetime.date(2024, 3, 1), "food", Decimal("-1.5"), "lunch out"))

    def test_hash_inside_note_and_inner_whitespace(self):
        self.assertEqual(parse("2024-03-01 x 1 a  #  b ")[0].note, "a  #  b")

    def test_tabs_as_separators(self):
        e = parse("2024-03-01\t\tx\t1\tn")[0]
        self.assertEqual((e.category, e.amount, e.note), ("x", Decimal("1"), "n"))


class AmountTest(unittest.TestCase):
    def test_invalid_amounts(self):
        for bad in (".5", "5.", "+-1", "1e3", "NaN", "12.505", "1,000.00", "abc", "١٢", "-", "+"):
            with self.subTest(bad=bad):
                with self.assertRaises(ParseError) as cm:
                    parse(f"2024-03-01 x {bad}")
                self.assertEqual(cm.exception.line, 1)

    def test_valid_amounts(self):
        cases = {"-0": "0", "+0": "0", "007": "7", "+2500": "2500", "12.5": "12.5",
                 "12": "12", "-0.99": "-0.99", "2500.00": "2500"}
        for text, value in cases.items():
            with self.subTest(text=text):
                amount = parse(f"2024-03-01 x {text}")[0].amount
                self.assertIsInstance(amount, Decimal)
                self.assertEqual(amount, Decimal(value))

    def test_invalid_amount_message(self):
        with self.assertRaises(ParseError) as cm:
            parse("\n\n2024-03-01 x abc")
        self.assertIn("line 3", str(cm.exception))
        self.assertIn("'abc'", str(cm.exception))


class LineErrorTest(unittest.TestCase):
    def test_bad_lines_report_line_number(self):
        prefix = "# comment\n\n   \n2024-03-01 ok 1\n"  # bad line is line 5
        for bad in ("2024-02-30 x 1", "2024-3-01 x 1", "24-03-01 x 1", "2024-03-01 x",
                    "2024-13-01 x 1", "2024-03-01", "x"):
            with self.subTest(bad=bad):
                with self.assertRaises(ParseError) as cm:
                    parse(prefix + bad + "\n2024-03-02 ok 2\n")
                err = cm.exception
                self.assertEqual(err.line, 5)
                self.assertIsInstance(err, ValueError)
                self.assertIn("line 5", str(err))

    def test_crlf_line_numbers(self):
        with self.assertRaises(ParseError) as cm:
            parse("# c\r\n\r\n2024-02-30 x 1\r\n")
        self.assertEqual(cm.exception.line, 3)


class BalanceTest(unittest.TestCase):
    def test_empty(self):
        result = balance([])
        self.assertIsInstance(result, Decimal)
        self.assertEqual(result, Decimal("0"))

    def test_sample(self):
        self.assertEqual(balance(parse(SAMPLE)), Decimal("1557.50"))


class FormatTest(unittest.TestCase):
    def test_format_amount(self):
        self.assertEqual(format_amount(Decimal("-0")), "0.00")
        self.assertEqual(format_amount(Decimal("-0.00")), "0.00")
        self.assertEqual(format_amount(Decimal("0")), "0.00")
        self.assertEqual(format_amount(Decimal("-900")), "-900.00")
        self.assertEqual(format_amount(Decimal("12.5")), "12.50")
        self.assertEqual(format_amount(Decimal("-0.05")), "-0.05")
        self.assertEqual(format_amount(Decimal("-10")), "-10.00")

    def test_negative_zero_sum(self):
        total = balance(parse("2024-03-01 x -1.50\n2024-03-02 y 1.5\n2024-03-03 z -0"))
        self.assertEqual(format_amount(total), "0.00")

    def test_format_entry(self):
        e = parse("2024-03-02 Groceries -42.5   weekly  shop ")[0]
        self.assertEqual(format_entry(e), "2024-03-02 groceries -42.50 weekly  shop")
        self.assertEqual(format_entry(parse("2024-03-05 Rent -900")[0]), "2024-03-05 rent -900.00")


if __name__ == "__main__":
    unittest.main()
